Inline prefix packing:
```cpp
static void pack_inline(Row256& row, int& pos, const ScampPrefix& p, int origin) {
   uint64_t frag; uint32_t len;
   if (origin==0) { frag = scamp_hi(p.addr); len = p.len; }
   else if (origin==16) { frag = (scamp_hi(p.addr) & 0xFFFFFFFFFFFFULL) << 16; len = p.len - 16; }
   else { frag = scamp_lo(p.addr); len = p.len - 64; }
   pk_write(row,pos,frag,64);
   pk_write(row,pos,len,8);
   pk_write(row,pos,p.hop,22);
}
