            uint32_t hop = d->nexthops[n.ni_base + off];
            off++;
            ScampPrefix sp; sp.addr = addr; sp.len = (uint8_t)L; sp.hop = hop;
            if (hop > SCAMP_HOP_MAX) return false;
            fib.push_back(sp);
            if (fib.size() > SCAMP_PREFIX_LIMIT) return false;
        }
