#include "image_validate.h"
#include "fib.h"

#include <algorithm>
#include <deque>
#include <vector>

namespace {

struct ChildRef {
    uint8_t key;
    int stage;
    uint32_t cell;
    int32_t node;
};

struct ValNode {
    int32_t stage = 0;
    uint32_t cell = 0;
    uint8_t slot = 0, rec = 0, type = NODE_NONE, origin = 0, depth = 0;
    uint32_t bmp = SCAMP_BMP_NULL, bitmap_id = 0, ni_base = 0;
    uint64_t pattern = 0;
    u128_t region = 0;
    int32_t parent = -1;
    uint32_t owned = 0;
    uint32_t ch_start = 0;
    uint8_t ch_count = 0;
    uint8_t ninl = 0;
    ScampPrefix inl[2];
};

struct Work {
    int stage = 0;
    uint32_t cell = 0;
    bool bulk = false;
    int origin = 0;
    int depth = 0;
    u128_t region = 0;
    int32_t parent = -1;
    int32_t ref = -1;
};

struct Validator {
    const ImageData* d = nullptr;
    ParsedImage* out = nullptr;
    std::vector<int32_t> cover[RAM_NUM];
    std::deque<ValNode> nodes;
    std::vector<ChildRef> children;
    std::vector<ScampPrefix> fib;
    std::vector<Work> q;

    bool run();
    bool shape();
    bool visit(const Work& w);
    bool finish();
    int32_t resolve(const ImageLoc& loc) const;
};

int32_t Validator::resolve(const ImageLoc& loc) const {
    if (loc.stage < 0 || loc.stage >= RAM_NUM) return -1;
    if (loc.cell >= d->cells[loc.stage]) return -1;
    int32_t id = cover[loc.stage][loc.cell];
    if (id < 0) return -1;
    if (nodes[id].cell != loc.cell) return -1;   /* must be the slot start */
    return id;
}

bool Validator::shape() {
    if (d->cells.size() != RAM_NUM || d->banks.size() != RAM_NUM) return false;
    if (d->front16.size() > SCAMP_FRONT_LIMIT) return false;
    if (d->front64.size() > SCAMP_FRONT_LIMIT) return false;
    if (d->bitmaps.size() > SCAMP_BITMAP_LIMIT) return false;
    if (d->nexthops.size() > SCAMP_NI_LIMIT) return false;
    uint64_t rows = 0;
    for (int s = 0; s < RAM_NUM; ++s) {
        if (d->cells[s] > SCAMP_CELL_LIMIT) return false;
        uint32_t want = (d->cells[s] + 1) / 2;
        if (d->banks[s].size() != want) return false;
        rows += want;
    }
    if (rows > SCAMP_ROW_LIMIT) return false;
    for (size_t i = 0; i < d->nexthops.size(); ++i)
        if (d->nexthops[i] > SCAMP_HOP_MAX) return false;
    if (d->root.stage != -1) {
        if (d->root.stage < 0 || d->root.stage > SCAMP_STAGE_MAX) return false;
        if (d->root.cell >= d->cells[d->root.stage]) return false;
    }
    for (int which = 0; which < 2; ++which) {
        const std::vector<ImageFront>& v = which ? d->front64 : d->front16;
        uint64_t limit = which ? ~0ULL : 0xFFFFULL;
        uint64_t prev = 0;
        for (size_t i = 0; i < v.size(); ++i) {
            if (v[i].key > limit) return false;
            if (i && !(prev < v[i].key)) return false;      /* sorted, unique */
            prev = v[i].key;
            if (v[i].loc.stage < 0 || v[i].loc.stage > SCAMP_STAGE_MAX) return false;
            if (v[i].loc.cell >= d->cells[v[i].loc.stage]) return false;
        }
    }
    return true;
}

bool Validator::visit(const Work& w) {
    int s = w.stage;
    if (s < 0 || s >= RAM_NUM) return false;
    uint32_t C = d->cells[s];
    if (w.cell >= C) return false;
    int max = scamp_origin_max(w.origin);
    if (w.depth < 0 || w.depth > max) return false;
    if ((w.depth - w.origin) % 6 != 0) return false;

    const Row256& row = d->banks[s][w.cell / 2];
    int base = (w.cell & 1u) ? 128 : 0;
    int type = static_cast<int>(pk_read(row, base + PK_TYPE_OFF, PK_TYPE_BITS));
    if (type < TYPE1 || type > TYPE5) return false;
    int rec = scamp_type_cells(type);
    if (rec == 2 && (w.cell & 1u)) return false;             /* even alignment */
    int slot = w.bulk ? 2 : rec;
    if (w.cell + static_cast<uint32_t>(slot) > C) return false;

    int32_t idx = static_cast<int32_t>(nodes.size());
    for (int k = 0; k < slot; ++k) {
        if (cover[s][w.cell + k] != -1) return false;        /* overlap / two parents */
        cover[s][w.cell + k] = idx;
    }
    if (slot == 2 && rec == 1) {                             /* bulk zero padding */
        if (!pk_zero(row, 128, 128)) return false;
    }

    nodes.emplace_back();
    ValNode& n = nodes[idx];
    n.stage = s;
    n.cell = w.cell;
    n.slot = static_cast<uint8_t>(slot);
    n.rec = static_cast<uint8_t>(rec);
    n.type = static_cast<uint8_t>(type);
    n.origin = static_cast<uint8_t>(w.origin);
    n.depth = static_cast<uint8_t>(w.depth);
    n.region = w.region;
    n.parent = w.parent;
    if (w.ref >= 0) children[w.ref].node = idx;

    n.bmp = static_cast<uint32_t>(pk_read(row, base + PK_BMP_OFF, PK_BMP_BITS));

    /* ---- NI header ---- */
    if (type <= TYPE3) {
        uint32_t bid = static_cast<uint32_t>(pk_read(row, base + PK_BID_OFF, PK_BID_BITS));
        uint32_t nib = static_cast<uint32_t>(pk_read(row, base + PK_NIB_OFF, PK_NIB_BITS));
        if (bid >= d->bitmaps.size()) return false;
        n.bitmap_id = bid;
        n.ni_base = nib;
        n.pattern = d->bitmaps[bid];
        if (n.pattern & 1ULL) return false;                  /* bit0 unused */
        uint32_t pc = scamp_popcount64(n.pattern);
        if (static_cast<uint64_t>(nib) + pc > d->nexthops.size()) return false;
        if (pc == 0 && nib != 0) return false;               /* empty arrays: base0 */
        if (type == TYPE1 && !pk_zero(row, base + PK_T1_RSVD_OFF, 1)) return false;
        if (type == TYPE2 && !pk_zero(row, base + PK_T2_RSVD_OFF, 1)) return false;
        if (type == TYPE3 && !pk_zero(row, base + PK_T3_RSVD_OFF, PK_T3_RSVD_BITS)) return false;
    }

    /* ---- explicit / direct children ---- */
    int nslots = (type == TYPE1) ? 2 : (type == TYPE2 ? 6 : (type == TYPE3 ? 3 : 0));
    int cbase = (type == TYPE3) ? PK_T3_DIRECT : (type == TYPE1 ? PK_T1_CHILD : PK_T2_CHILD);
    uint64_t direct_keys = 0;
    bool seen_absent = false;
    int last_key = -1;
    uint32_t nchild = 0;
    n.ch_start = static_cast<uint32_t>(children.size());
    for (int i = 0; i < nslots; ++i) {
        uint32_t v = static_cast<uint32_t>(pk_read(row, base + cbase + 32 * i, 32));
        int key = static_cast<int>(v & 0x3Fu);
        int cst = static_cast<int>((v >> 6) & 0xFu);
        uint32_t ccell = v >> 10;
        if (cst == SCAMP_ABSENT_STAGE) {
            if (v != SCAMP_CHILD_ABSENT) return false;       /* only absent encoding */
            seen_absent = true;
            continue;
        }
        if (cst > SCAMP_STAGE_MAX) return false;             /* present stages 0..10 */
        if (seen_absent) return false;                       /* present first */
        if (key <= last_key) return false;                   /* sorted, distinct */
        last_key = key;
        if (cst >= s) return false;                          /* strictly lower stage */
        if (w.depth + 6 > max) return false;                 /* child past owner max */
        direct_keys |= (1ULL << key);
        ChildRef cr;
        cr.key = static_cast<uint8_t>(key);
        cr.stage = cst;
        cr.cell = ccell;
        cr.node = -1;
        int32_t ref = static_cast<int32_t>(children.size());
        children.push_back(cr);
        ++n.ch_count;
        ++nchild;
        Work cw;
        cw.stage = cst;
        cw.cell = ccell;
        cw.bulk = false;
        cw.origin = w.origin;
        cw.depth = w.depth + 6;
        cw.region = w.region | (static_cast<u128_t>(key) << (128 - (w.depth + 6)));
        cw.parent = idx;
        cw.ref = ref;
        q.push_back(cw);
    }

