        uint32_t bbase = static_cast<uint32_t>(pk_read(row, base + PK_BULK_BASE_OFF, PK_BULK_BASE_BITS));
        int bstg = static_cast<int>(pk_read(row, base + PK_BULK_STG_OFF, PK_BULK_STG_BITS));
        if (bstg > SCAMP_STAGE_MAX) return false;
        if (bstg >= s) return false;
        if (bbase & 1u) return false;                        /* bulk_base even */
        uint32_t bc = scamp_popcount64(bm);
        if (bc < 4) return false;                            /* at least four bulk */
        if (static_cast<uint64_t>(bbase) + 2ull * bc > d->cells[bstg]) return false;
        if (w.depth + 6 > max) return false;
        if (bm & direct_keys) return false;                  /* disjoint keys */
        uint32_t i = 0;
        for (int k = 0; k < 64; ++k) {
